import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.D5wUhsuj.js";const h=JSON.parse('{"title":"Agent Experience and Skill Evolution","description":"","frontmatter":{},"headers":[],"relativePath":"en/05-agent-experience-and-skill-evolution.md","filePath":"en/05-agent-experience-and-skill-evolution.md"}'),o={name:"en/05-agent-experience-and-skill-evolution.md"};function s(l,e,r,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="agent-experience-and-skill-evolution" tabindex="-1">Agent Experience and Skill Evolution <a class="header-anchor" href="#agent-experience-and-skill-evolution" aria-label="Permalink to &quot;Agent Experience and Skill Evolution&quot;">​</a></h1><blockquote><p>Documentation version: 1.0.0. This manual describes the implemented Agent-side validation, experience, Lesson, and Skill-evolution path over AgentTask records.</p></blockquote><h2 id="_1-purpose-and-boundary" tabindex="-1">1. Purpose and boundary <a class="header-anchor" href="#_1-purpose-and-boundary" aria-label="Permalink to &quot;1. Purpose and boundary&quot;">​</a></h2><p>PhyAgentOS learns at task/workflow granularity rather than from an isolated tool call. A completed, semantically verified AgentTask with all of its PlanRevisions may become one <code>TaskEpisode</code>. Background reflection can then support a reusable Skill workflow or a scoped Lesson.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill activation</span></span>
<span class="line"><span>  → AgentTask + PlanRevisions + ToolInvocations</span></span>
<span class="line"><span>  → semantic task outcome</span></span>
<span class="line"><span>  → redacted TaskEpisode</span></span>
<span class="line"><span>  → asynchronous reflection</span></span>
<span class="line"><span>      ├─ successful reusable workflow → SkillCandidate</span></span>
<span class="line"><span>      └─ workflow-related failure     → FailureObservation → LessonCluster</span></span></code></pre></div><p>This path does not modify AgentTask state, Forge Tool calls, Gateway payloads, evidence collection, recovery ordering, or lower-level execution. If initialization, persistence, a model call, validation, or a write fails, evolution fails open and the original task outcome is preserved.</p><p>The initial outcome provider is Forge. The <code>TaskOutcomeSource</code> protocol allows a later runtime to produce the same <code>TaskOutcomeEnvelope</code> without changing Lesson or Skill evolution.</p><h2 id="_2-skill-activation-and-task-attribution" tabindex="-1">2. Skill activation and task attribution <a class="header-anchor" href="#_2-skill-activation-and-task-attribution" aria-label="Permalink to &quot;2. Skill activation and task attribution&quot;">​</a></h2><p>When <code>agents.evolution.enabled=true</code>, Agent context includes Skill summaries and tells the Agent to check them before its first tool call. A matching workflow is activated through:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>activate_skill(name, role=&quot;primary&quot; | &quot;supporting&quot;)</span></span></code></pre></div><p>Activation rules:</p><ul><li><code>name</code> must be an exact registered hyphen-case Skill name; paths are rejected;</li><li>workspace Skills override installed and built-in Skills with the same name; installed Skills override built-ins;</li><li>unavailable Skills cannot be activated;</li><li>a turn may have one primary Skill and multiple supporting Skills;</li><li>the same Skill cannot change role within the turn;</li><li>only the primary Skill may be automatically updated;</li><li>primary and supporting Skills may receive relevant failure attribution;</li><li>reading <code>SKILL.md</code> through a file tool does not count as activation.</li></ul><p>The result contains the complete Skill document, activation ID, source, content digest, and applicable active Lessons. The digest fixes attribution to the revision used by the current turn; a promoted revision becomes visible through the summary on a later turn.</p><p>AgentLoop records ordered tool names and argument field names, not argument values. A Forge AgentTask requires the current turn&#39;s primary activation; creation revalidates and freezes the exact Skill version, Runtime, manifest/workflow hashes, and required ToolSpecs. Bound Query/Action/Session records and Gateway invocation references are attached as execution proceeds. Diagnostic Query without a task is not attributed to a task episode.</p><p>The binding also freezes the applicable active Lessons returned by each activated Skill. Automatic verification, every later PlanRevision, and review resolve Lesson context through the task ID, so they see the same bounded set even if the Lesson ledger changes afterward. These Lessons are non-authoritative workflow advisories: they may suggest a check, but they cannot establish a criterion status, replace execution facts or evidence, or be cited as evidence references. A task without an activated Skill supplies an empty Lesson set.</p><h2 id="_3-outcome-and-episode-classification" tabindex="-1">3. Outcome and episode classification <a class="header-anchor" href="#_3-outcome-and-episode-classification" aria-label="Permalink to &quot;3. Outcome and episode classification&quot;">​</a></h2><p><code>AgentTaskOutcomeSource</code> reads the persisted AgentTask and produces:</p><ul><li>redacted goal and criteria;</li><li>final semantic verdict and per-criterion statuses;</li><li>each PlanRevision&#39;s Query/Action/Session semantics, input field names, execution status, verdict, and redacted reason;</li><li>opaque task, revision, invocation, attempt, and evidence fingerprints;</li><li>primary/supporting activations and the redacted workflow trace.</li></ul><p>It does not copy raw tool output, input values, evidence locators, endpoints, credentials, absolute paths, or executable Gateway IDs into learned content. Task, revision, invocation, and attempt identities remain opaque internal references and cannot appear in generated Lessons or Skills.</p><p>The outcome policy is:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Outcome</th><th style="text-align:left;">Experience behavior</th></tr></thead><tbody><tr><td style="text-align:left;">Final <code>success</code>, every criterion <code>satisfied</code></td><td style="text-align:left;">May support a reusable Skill candidate</td></tr><tr><td style="text-align:left;">Final <code>failure</code> or <code>replan_required</code></td><td style="text-align:left;">May produce workflow-related failure observations</td></tr><tr><td style="text-align:left;">Failed/replanned revision followed by final success</td><td style="text-align:left;"><code>mixed</code>: may support both recovery workflow and failure observations</td></tr><tr><td style="text-align:left;"><code>inconclusive</code>, invalid verdict, verifier/service error</td><td style="text-align:left;">Diagnostic only; no promotable experience</td></tr><tr><td style="text-align:left;"><code>verification=off</code></td><td style="text-align:left;">No semantic learning</td></tr><tr><td style="text-align:left;">Manual review</td><td style="text-align:left;">Does not create another episode or support count</td></tr></tbody></table><p>The database has a unique AgentTask constraint. PlanRevisions, duplicate completion events, process replay, and review attempts therefore remain one episode and one unit of independent support.</p><h2 id="_4-background-reflection" tabindex="-1">4. Background reflection <a class="header-anchor" href="#_4-background-reflection" aria-label="Permalink to &quot;4. Background reflection&quot;">​</a></h2><p>The coordinator creates the episode and pending job synchronously, then runs model-backed reflection in an <code>asyncio</code> task. On restart, interrupted jobs return to pending. Transient job failures retry with bounded attempts; a final failure remains observable but does not affect Forge.</p><p>The reflection model receives structured, redacted episode data, active candidates, active Lessons, Lesson clusters, and the registered Skill catalog. Task text, traces, verdict text, and evidence labels are explicitly treated as untrusted data. The response must validate as <code>experience_assessment_v1</code>.</p><p>Evolution calls use <code>maxEvolutionCallsPerRun</code>, which is independent of <code>maxVerifierCallsPerRun</code>. When the budget is exhausted, pending work is deferred rather than converted into a task failure.</p><h2 id="_5-lesson-eligibility-and-observations" tabindex="-1">5. Lesson eligibility and observations <a class="header-anchor" href="#_5-lesson-eligibility-and-observations" aria-label="Permalink to &quot;5. Lesson eligibility and observations&quot;">​</a></h2><p>A failed or replanned attempt is not automatically a Skill failure. Every proposed observation carries <code>LessonEligibility</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Decision/reason</th><th style="text-align:left;">Handling</th></tr></thead><tbody><tr><td style="text-align:left;"><code>related / workflow_related</code></td><td style="text-align:left;">Eligible for normalization and clustering</td></tr><tr><td style="text-align:left;"><code>unrelated / task_unsatisfiable</code></td><td style="text-align:left;">Diagnostic only</td></tr><tr><td style="text-align:left;"><code>unrelated / verifier_limit</code></td><td style="text-align:left;">Diagnostic only</td></tr><tr><td style="text-align:left;"><code>unrelated / evidence_limit</code></td><td style="text-align:left;">Diagnostic only</td></tr><tr><td style="text-align:left;"><code>unrelated / external_or_infrastructure</code></td><td style="text-align:left;">Diagnostic only</td></tr><tr><td style="text-align:left;"><code>unrelated / user_constraint</code></td><td style="text-align:left;">Diagnostic only</td></tr><tr><td style="text-align:left;"><code>uncertain / unknown</code></td><td style="text-align:left;">Diagnostic only</td></tr></tbody></table><p>An eligible <code>FailureObservation</code> contains a Skill binding when available, workflow key, canonical pattern key, generalized pattern summary, <code>applies_when</code>, <code>does_not_apply_when</code>, and a recovery principle. It must not contain a concrete task answer, object name/value, coordinate, option, endpoint, Gateway ID, raw input, or tool output.</p><p>Without an activated Skill, the observation remains in an unbound cluster. An exact workflow-key match from a later Skill candidate can bind that cluster; unrelated workflows are never merged.</p><h2 id="_6-lesson-clustering-and-activation" tabindex="-1">6. Lesson clustering and activation <a class="header-anchor" href="#_6-lesson-clustering-and-activation" aria-label="Permalink to &quot;6. Lesson clustering and activation&quot;">​</a></h2><p>The reflection model first tries to match an existing cluster with the same Skill and workflow. Otherwise, a stable cluster identity is derived from Skill/unbound scope, workflow key, and normalized pattern key. The initial implementation does not use embeddings or a vector database.</p><p>Each cluster has one of these states:</p><table tabindex="0"><thead><tr><th style="text-align:left;">State</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>collecting</code></td><td style="text-align:left;">Fewer than <code>minLessonEpisodes</code> independent AgentTasks, or reopened after counterevidence</td></tr><tr><td style="text-align:left;"><code>blocked</code></td><td style="text-align:left;">Synthesis or abstraction/content validation failed</td></tr><tr><td style="text-align:left;"><code>activated</code></td><td style="text-align:left;">A validated <code>ScopedLesson</code> exists</td></tr></tbody></table><p>Support is unique on <code>(cluster_id, root_task_id)</code>, where the stable root reference identifies an AgentTask. With the default <code>minLessonEpisodes=3</code>, the first two related failures remain collecting. The third distinct task schedules synthesis.</p><p>Synthesis receives only normalized observations from the cluster. A Lesson proposal must include:</p><ul><li>explicit applicable and non-applicable conditions;</li><li>the invariant failure mode;</li><li>a reusable check, decision principle, or recovery recommendation;</li><li>optional same-scope Lessons that it supersedes.</li></ul><p>Activation requires both:</p><ol><li>static content policy approval; and</li><li><code>lesson_abstraction_validation_v1</code> with <code>reusable=true</code>, <code>contains_specific_answer=false</code>, no <code>unsupported_literals</code>, and confidence at least <code>0.8</code>.</li></ol><p>The static policy rejects credentials, endpoints, absolute paths, executable IDs, Action Manifest copies, fixed action/input assignments, bypass-verification instructions, prompt injection, answer/option phrases, coordinates, and fixed numeric answers. A rejected cluster stays blocked and is never loaded into Agent context.</p><h2 id="_7-scoped-lesson-retrieval-and-lifecycle" tabindex="-1">7. Scoped Lesson retrieval and lifecycle <a class="header-anchor" href="#_7-scoped-lesson-retrieval-and-lifecycle" aria-label="Permalink to &quot;7. Scoped Lesson retrieval and lifecycle&quot;">​</a></h2><p>An active <code>ScopedLesson</code> records:</p><ul><li>Skill and workflow scope;</li><li><code>applies_when</code> and <code>does_not_apply_when</code>;</li><li>failure mode, recommendation, and severity;</li><li>cluster and supporting episode IDs;</li><li>observation count and counterexample lineage;</li><li><code>active</code>, <code>inactive</code>, <code>superseded</code>, or <code>retired</code> status.</li></ul><p><code>activate_skill</code> queries only active Lessons bound to that Skill. A lightweight term-overlap score compares the current task summary with applicability and exclusion text, then prefers stronger overlap, more observations, and newer updates. At most <code>maxLessonsPerSkill</code> entries are returned. Unbound, collecting, blocked, inactive, superseded, and retired material is not injected.</p><p>A validated narrower Lesson may supersede only an active Lesson in the same Skill/workflow scope. Successful episodes can identify directly contradicted active Lessons. After the configured independent-success threshold, the Lesson is retired and its cluster is reopened for narrower evidence.</p><p>Stable safety constraints stay in operator-owned <code>AGENTS.md</code> or <code>EMBODIED.md</code>; the evolution subsystem never writes those files.</p><h2 id="_8-skill-candidates-and-guarded-promotion" tabindex="-1">8. Skill candidates and guarded promotion <a class="header-anchor" href="#_8-skill-candidates-and-guarded-promotion" aria-label="Permalink to &quot;8. Skill candidates and guarded promotion&quot;">​</a></h2><p>A semantically successful or successfully recovered reusable episode may create or merge a <code>SkillCandidate</code>. Candidates are grouped by Skill name and workflow key; synonymous duplicates should reuse an existing Skill/candidate.</p><p>Promotion rules:</p><ul><li>each AgentTask episode contributes at most once;</li><li>the default <code>minSuccessfulEpisodes=3</code> requires three independent successes;</li><li>an update must target the activated primary Skill;</li><li>a task with a primary Skill cannot create a replacement Skill;</li><li>active same-workflow Lessons and reflection conflicts block promotion;</li><li>structural, content-policy, and reload validation must pass.</li></ul><p>Learned workflow content is restricted to a trigger/description, preconditions, generalized steps, verification checkpoints, recovery guidance, and applicability boundaries. Scripts, assets, Action Manifest copies, fixed Gateway actions/IDs, endpoints, credentials, and Forge/Verifier bypass instructions are forbidden.</p><p>New Skills are written to <code>workspace/skills/&lt;name&gt;/SKILL.md</code> with <code>always: false</code>. Existing workspace Skills retain human-authored text; only the marked block is replaced:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- paos:learned-workflow:start --&gt;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>&lt;!-- paos:learned-workflow:end --&gt;</span></span></code></pre></div><p>Built-in Skills are never modified in place. Their baseline is archived, copied into a workspace override, forced to non-always-on behavior, and then given the managed block. Writes are atomic, old workspace revisions are archived, the Skill is reloaded from workspace, and any failure rolls back the prior file.</p><h2 id="_9-persistence-and-projections" tabindex="-1">9. Persistence and projections <a class="header-anchor" href="#_9-persistence-and-projections" aria-label="Permalink to &quot;9. Persistence and projections&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/.paos/evolution/</span></span>
<span class="line"><span>├── experience.sqlite3</span></span>
<span class="line"><span>└── revisions/&lt;skill&gt;/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;workspace&gt;/skills/&lt;skill&gt;/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>└── references/LESSONS.md</span></span></code></pre></div><p><code>experience.sqlite3</code> is the source of truth and uses SQLite WAL. It stores bindings, episodes, reflection jobs, observations, clusters, unique AgentTask support, cluster jobs, scoped Lessons, candidates, events, and migration metadata.</p><p><code>references/LESSONS.md</code> is generated atomically for review. It separates active/historical Lessons from collecting/blocked clusters and reports independent support and validation state. Manual edits to this projection are not authoritative.</p><p>The root <code>LESSONS.md</code> is preserved. On first evolution startup, legacy <code>- Lesson:</code> entries are imported once as inactive, unbound records. While evolution is enabled, the root file is neither global Agent context nor Forge Verifier input. Pre-cluster active database Lessons are also deactivated and must be reconstructed from known source roots, synthesized, and validated before reactivation. Disabling evolution restores the former global Agent-context, verifier-input, and verifier-append behavior without deleting evolution data.</p><h2 id="_10-observability-and-extension" tabindex="-1">10. Observability and extension <a class="header-anchor" href="#_10-observability-and-extension" aria-label="Permalink to &quot;10. Observability and extension&quot;">​</a></h2><p>Structured events include episode creation, assessment completion, eligibility rejection, observation clustering, cluster support/block/activation, Lesson supersession/retirement, candidate support/block/promotion, validation rejection, budget deferral, built-in baseline archive, and revision rollback. Operational logs use IDs and bounded summaries rather than raw sensitive values.</p><p>To add another trusted task outcome provider:</p><ol><li>implement <code>TaskOutcomeSource.build(task_ref)</code>;</li><li>return <code>task_outcome_envelope_v1</code> with semantic verdict, criteria, lineage, and opaque references;</li><li>preserve AgentTask-level idempotency and redaction;</li><li>schedule completion through <code>ExperienceCoordinator</code>;</li><li>do not place provider-private execution fields into Lesson or Skill contracts.</li></ol><p>This boundary also allows other trusted task providers to reuse Lesson clustering and Skill promotion without changing the Forge Tool API.</p><h2 id="next-reading" tabindex="-1">Next reading <a class="header-anchor" href="#next-reading" aria-label="Permalink to &quot;Next reading&quot;">​</a></h2><ul><li><a href="/docs/en/01-framework-introduction">Framework Introduction</a></li><li><a href="/docs/en/02-user-manual">User Manual</a></li><li><a href="/docs/en/03-developer-manual">Developer Manual</a></li><li><a href="/docs/en/04-forge-configuration-reference">Forge Configuration Reference</a></li><li><a href="/docs/en/">Documentation Index</a></li></ul>`,67)])])}const v=t(o,[["render",s]]);export{h as __pageData,v as default};
